process BLAST_BLASTP {
    tag "$meta.id"
    label 'process_medium'

    conda "${moduleDir}/environment.yml"
    container "${ workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container ?
        'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/0c/0c86cbb145786bf5c24ea7fb13448da5f7d5cd124fd4403c1da5bc8fc60c2588/data':
        'community.wave.seqera.io/library/blast:2.17.0--d4fb881691596759' }"

    input:
    tuple val(meta) , path(fasta)
    tuple val(meta2), path(db)
    val out_ext

    output:
    tuple val(meta), path("*.xml*") , emit: xml, optional: true
    tuple val(meta), path("*.tsv*") , emit: tsv, optional: true
    tuple val(meta), path("*.csv*") , emit: csv, optional: true
    tuple val("${task.process}"), val("blastp"), eval("blastp -version 2>&1 | sed 's/^.*blastp: //; s/ .*\$//'"), topic: versions, emit: versions_blastp

    when:
    task.ext.when == null || task.ext.when

    script:
    def args = task.ext.args ?: ''
    def prefix = task.ext.prefix ?: "${meta.id}"
    def is_compressed = fasta.getExtension() == "gz" ? true : false
    def fasta_name = is_compressed ? fasta.getBaseName() : fasta
    def uncompress_input = is_compressed ? "gzip -c -d ${fasta} > ${fasta_name}" : ''

    def outfmt = 6
    if ( "$out_ext" ==~ /^xml(\.gz)?$/ ) {
        outfmt = 5
    } else if ( "$out_ext" ==~ /^tsv(\.gz)?$/ ) {
        outfmt = 6
    } else if ( "$out_ext" ==~ /^csv(\.gz)?$/ ) {
        outfmt = 10
    } else {
        out_ext = 'tsv'
        outfmt = 6
        log.warn("Unknown output file format provided (${out_ext}): selecting BLAST default of tabular BLAST output (tsv)")
    }

    def out_ext_sans_gz = "$out_ext" - ~/\.gz$/
    def compress_output = "$out_ext" ==~ /^\w+\.gz$/ ? "gzip ${prefix}.${out_ext_sans_gz}" : ''

    """
    $uncompress_input

    DB=`find -L ./ -name "*.phr" | sed 's/\\.phr\$//'`
    blastp \\
        -query ${fasta_name} \\
        -out ${prefix}.${out_ext_sans_gz} \\
        -db \$DB \\
        -num_threads ${task.cpus} \\
        -outfmt ${outfmt} \\
        ${args}

    $compress_output

    """

    stub:
    def prefix = task.ext.prefix ?: "${meta.id}"

    def outfmt = 6
    if ( "$out_ext" ==~ /^xml(\.gz)?$/ ) {
        outfmt = 5
    } else if ( "$out_ext" ==~ /^tsv(\.gz)?$/ ) {
        outfmt = 6
    } else if ( "$out_ext" ==~ /^csv(\.gz)?$/ ) {
        outfmt = 10
    } else {
        out_ext = 'tsv'
        outfmt = 6
        log.warn("Unknown output file format provided (${out_ext}): selecting BLAST default of tabular BLAST output (tsv)")
    }

    def out_ext_sans_gz = "$out_ext" - ~/\.gz$/
    def compress_output = "$out_ext" ==~ /^\w+\.gz$/ ? "gzip ${prefix}.${out_ext_sans_gz}" : ''

    """
    touch ${prefix}.${out_ext_sans_gz}

    $compress_output

    """
}

nextflow_process {

    name "Test Process BLAST_BLASTP"
    script "../main.nf"
    process "BLAST_BLASTP"
    config "./nextflow.config"
    tag "modules"
    tag "modules_nfcore"
    tag "blast"
    tag "blast/blastp"
    tag "blast/makeblastdb"

    setup {
        run("BLAST_MAKEBLASTDB") {
            script "../../makeblastdb/main.nf"
            process {
                """
                input[0] = [ [id:'test2'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = channel.of([])
                """
            }
        }
    }

    test("Should search for proteins against a blast db and return the default (tsv) file with hits") {

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = [ [id:'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = BLAST_MAKEBLASTDB.out.db
                input[2] = ''
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("Should search for zipped proteins against a blast db and return the default (tsv) file with hits") {

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = [ [id:'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta.gz', checkIfExists: true) ]
                input[1] = BLAST_MAKEBLASTDB.out.db
                input[2] = ''
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("Should search for proteins against a blast db and return an xml file with hits") {

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = [ [id:'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = BLAST_MAKEBLASTDB.out.db
                input[2] = 'xml'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("Should search for proteins against a blast db and return a tsv file with hits") {

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = [ [id:'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = BLAST_MAKEBLASTDB.out.db
                input[2] = 'tsv'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("Should search for proteins against a blast db and return a tsv.gz file with hits") {

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = [ [id:'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = BLAST_MAKEBLASTDB.out.db
                input[2] = 'tsv.gz'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("Should search for proteins against a blast db and return a csv file with hits") {

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = [ [id:'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = BLAST_MAKEBLASTDB.out.db
                input[2] = 'csv'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("Should search for proteins against a blast db and return a tsv.gz file with hits - stub") {

        options '-stub'

        when {
            params {
                outdir = "$outputDir"
            }
            process {
                """
                input[0] = [ [id:'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = BLAST_MAKEBLASTDB.out.db
                input[2] = 'tsv.gz'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

